import [IO] from "std/io.bpl";

# Using C math functions via extern (std/math.bpl wraps these)
extern sqrt(x: float) ret float;
extern pow(base: float, exp: float) ret float;
extern sin(x: float) ret float;
extern cos(x: float) ret float;
extern floor(x: float) ret float;
extern ceil(x: float) ret float;

# Custom math functions
frame abs(n: int) ret int {
    if (n < 0) { return -n; }
    return n;
}

frame min(a: int, b: int) ret int {
    if (a < b) { return a; }
    return b;
}

frame max(a: int, b: int) ret int {
    if (a > b) { return a; }
    return b;
}

frame main() ret int {
    IO.print("=== Math Functions ===\n\n");

    # Basic operations
    IO.print("abs(-42) = ");
    IO.printInt(abs(-42));
    IO.print("\n");

    IO.print("min(10, 20) = ");
    IO.printInt(min(10, 20));
    IO.print("\n");

    IO.print("max(10, 20) = ");
    IO.printInt(max(10, 20));
    IO.print("\n");

    # Floating point
    IO.print("\nsqrt(16) = ");
    IO.printFloat(sqrt(16.0));
    IO.print("\n");

    IO.print("pow(2, 10) = ");
    IO.printFloat(pow(2.0, 10.0));
    IO.print("\n");

    IO.print("floor(3.7) = ");
    IO.printFloat(floor(3.7));
    IO.print("\n");

    IO.print("ceil(3.2) = ");
    IO.printFloat(ceil(3.2));
    IO.print("\n");

    return 0;
}

import [IO] from "std/io.bpl";
import [strlen], [strcmp] from "std/c.bpl";

# String utility functions
frame stringLength(s: string) ret int {
    return strlen(s);
}

frame stringsEqual(a: string, b: string) ret bool {
    return strcmp(a, b) == 0;
}

frame startsWith(s: string, prefix: string) ret bool {
    local prefixLen: int = strlen(prefix);
    local sLen: int = strlen(s);

    if (prefixLen > sLen) {
        return false;
    }

    # Compare character by character
    loop (local i: int = 0; i < prefixLen; i = i + 1) {
        # Access characters through pointer arithmetic
        local sChar: char = *(cast<*char>(s) + i);
        local pChar: char = *(cast<*char>(prefix) + i);
        if (sChar != pChar) {
            return false;
        }
    }
    return true;
}

frame main() ret int {
    IO.print("=== String Operations ===\n\n");

    local greeting: string = "Hello, World!";

    IO.print("String: ");
    IO.print(greeting);
    IO.print("\n");

    IO.print("Length: ");
    IO.printInt(stringLength(greeting));
    IO.print("\n");

    IO.print("\nComparisons:\n");
    IO.print("'abc' == 'abc': ");
    IO.printBool(stringsEqual("abc", "abc"));
    IO.print("\n");

    IO.print("'abc' == 'xyz': ");
    IO.printBool(stringsEqual("abc", "xyz"));
    IO.print("\n");

    IO.print("\nPrefix checks:\n");
    IO.print("'Hello...' starts with 'Hello': ");
    IO.printBool(startsWith(greeting, "Hello"));
    IO.print("\n");

    IO.print("'Hello...' starts with 'World': ");
    IO.printBool(startsWith(greeting, "World"));
    IO.print("\n");

    return 0;
}

import [IO] from "std/io.bpl";
import [malloc], [free] from "std/c.bpl";

# Simple dynamic array implementation
struct IntVec {
    data: *int,
    len: int,
    cap: int,

    frame create(capacity: int) ret IntVec {
        return IntVec {
            data: cast<*int>(malloc(capacity * sizeof<int>())),
            len: 0,
            cap: capacity
        };
    }

    frame push(this: *IntVec, value: int) {
        if (this.len < this.cap) {
            *(this.data + this.len) = value;
            this.len = this.len + 1;
        }
    }

    frame get(this: *IntVec, index: int) ret int {
        return *(this.data + index);
    }

    frame destroy(this: *IntVec) {
        free(cast<*void>(this.data));
    }
}

frame main() ret int {
    IO.print("=== Collections Demo ===\n\n");

    local vec: IntVec = IntVec.create(10);
    defer { vec.destroy(); }

    # Add elements
    vec.push(10);
    vec.push(20);
    vec.push(30);
    vec.push(40);
    vec.push(50);

    IO.print("Vector contents: ");
    loop (local i: int = 0; i < vec.len; i = i + 1) {
        IO.printInt(vec.get(i));
        IO.print(" ");
    }
    IO.print("\n");

    IO.print("Length: ");
    IO.printInt(vec.len);
    IO.print("\n");

    # Sum all elements
    local sum: int = 0;
    loop (local i: int = 0; i < vec.len; i = i + 1) {
        sum = sum + vec.get(i);
    }
    IO.print("Sum: ");
    IO.printInt(sum);
    IO.print("\n");

    return 0;
}

