import [IO] from "std/io.bpl";

frame sum(arr: *int, len: int) ret int {
    local total: int = 0;
    loop (local i: int = 0; i < len; i = i + 1) {
        total = total + *(arr + i);
    }
    return total;
}

frame average(arr: *int, len: int) ret float {
    local total: int = sum(arr, len);
    return cast<float>(total) / cast<float>(len);
}

frame findMax(arr: *int, len: int) ret int {
    local maxVal: int = *(arr);
    loop (local i: int = 1; i < len; i = i + 1) {
        if (*(arr + i) > maxVal) {
            maxVal = *(arr + i);
        }
    }
    return maxVal;
}

frame main() ret int {
    local data: int[6] = [5, 2, 8, 1, 9, 3];

    IO.print("Array: [5, 2, 8, 1, 9, 3]\n");
    IO.print("Sum: ");
    IO.printInt(sum(&data[0], 6));
    IO.print("\n");

    IO.print("Average: ");
    IO.printFloat(average(&data[0], 6));
    IO.print("\n");

    IO.print("Max: ");
    IO.printInt(findMax(&data[0], 6));
    IO.print("\n");

    return 0;
}
